# A mutable cell for C++ reference parameters: f(x) with x <- rosetta_ref(value) updates x$value.
rosetta_ref <- function(value = NULL) {
  ref <- new.env(parent = emptyenv())
  ref$value <- value
  class(ref) <- "rosetta_ref"
  ref
}
# The R6 subclass override of a virtual method, or NULL where the generated native method applies.
.rosetta_override <- function(self, name) {
  method <- get0(name, envir = self, inherits = FALSE)
  if (!is.function(method)) return(NULL)
  code <- body(method)
  if (is.call(code) && identical(code[[1L]], quote(invisible))) code <- code[[2L]]
  native <- is.call(code) && identical(code[[1L]], quote(.Call)) && is.name(code[[2L]]) && startsWith(as.character(code[[2L]]), ".rs_")
  if (native) NULL else method
}
